    private static Bitmap darkBitmap;
    private static Bitmap lightBitmap;

    public static Bitmap getBitmap(boolean isDark) {
        if (isDark) {
            synchronized (CheckboxPrimitiveKnob.class) {
                if (darkBitmap == null) darkBitmap = createBitmap(DARK_DATA, DARK_WIDTH, DARK_HEIGHT);
                return darkBitmap;
            }
        } else {
            synchronized (CheckboxPrimitiveKnob.class) {
                if (lightBitmap == null) lightBitmap = createBitmap(LIGHT_DATA, LIGHT_WIDTH, LIGHT_HEIGHT);
                return lightBitmap;
            }
        }
    }

    /**
     * Clears the static bitmap cache to free memory.
     * Optional method for memory management in low-memory situations.
     */
    public static void clearCache() {
        synchronized (CheckboxPrimitiveKnob.class) {
            if (darkBitmap != null) {
                darkBitmap.recycle();
                darkBitmap = null;
            }
            if (lightBitmap != null) {
                lightBitmap.recycle();
                lightBitmap = null;
            }
        }
    }

    private static Bitmap createBitmap(char[] data, int width, int height) {
        int[] pixels = new int[width * height];
        int pos = 0;
        for (int i = 0; i < data.length; i++) {
            int val = data[i];
            int colorIdx = (val >> 8) & 0xFF;
            int count = val & 0xFF;
            int color = PALETTE[colorIdx];
            for (int j = 0; j < count; j++) {
                if (pos < pixels.length) {
                    pixels[pos++] = color;
                }
            }
        }
        return Bitmap.createBitmap(pixels, width, height, Bitmap.Config.ARGB_8888);
    }
